                                                                                                                                                                                                               
  CREATE TABLE "STS_FEEDBACK"                                                                                                                                                                        
   (	"FEEDBACK_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"STATUS" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                               
	"FILE_ID" NUMBER(20,0),                                                                                                                                                                                       
	"USER_ID" NUMBER(20,0),                                                                                                                                                                                       
	"FEEDBACK_DATE" DATE,                                                                                                                                                                                         
	"FEEDBACK_CONTENT" VARCHAR2(2000),                                                                                                                                                                            
	"FEEDBACK_TYPE" NUMBER(1,0),                                                                                                                                                                                  
	"PROCESS_DATE" DATE,                                                                                                                                                                                          
	"PROCESS_USER_ID" NUMBER(20,0),                                                                                                                                                                               
	"REMARK" VARCHAR2(2000),                                                                                                                                                                                      
	"TENANT_ID" NUMBER(20,0) DEFAULT 3,                                                                                                                                                                           
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                    
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                         
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                    
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                           
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                             
	"DING_USER_ID" VARCHAR2(512),                                                                                                                                                                                 
	 PRIMARY KEY ("FEEDBACK_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                          
   ) ;                                                                                                                                                                                                         

